/*
	rects in the wind #genuary8 #genuary #genuary2508
	Draw one million of something.
	https://openprocessing.org/sketch/2503156
	#generativeart #creativecoding #p5js
*/
let cnt = 0;

function setup() {
  createCanvas(800, 600);
  frameRate(30);
  noFill();
  stroke("rgba(0,0,0,0.1)");
  rectMode(CENTER);
  loop();
  cnt = 0;
}

function draw() {
  // for (let j = 0; j < 1; j++) {
    if (cnt < 1000000) background("tan");

    let SZE = 100;
    for (let x = SZE * 0.75; x < width * 0.925; x += SZE * 0.00725) {
      push();
      const y = height / 4;
      const dF = noise(x / 23, y / 43, frameCount / 243) - 0.5;
      translate(x, y + SZE * 2 * dF);
      const angle = noise(x / 23, y / 41, frameCount / 243) * TWO_PI;
      const szeF = noise(x / 93, y / 121, frameCount / 343);
      rotate(angle);
      if (cnt < 1000000) {
        rect(0, 0, SZE * szeF); cnt++;
      }
      pop();
      if (cnt >= 1000000) {
        // noLoop() removed for animation
        console.log(cnt, ~~(millis() / 1000), "sec");
        break;
      }
    }

    let img = get(width/2, 0, width/2, height/2);
    image(img, width/4, height/2);
    img = get(0, 0, width/2, height/2);
    image(img, width/4, 0);

    // frame
    if (true) {
      push();
      const sw = 10;
      strokeWeight(sw);
      stroke("rgb(27,26,26)");
      fill("rgb(27,26,26)");
      rectMode(CORNER);
      if (false && cnt < 1000000) {
        rect(sw/2, sw/2, width - sw, height - sw); cnt++;
      }
      // fill("rgb(22,20,20)")
      if (true || cnt < 1000000) {
        rect(0, 0, width/4, height); cnt++;
        rect(width*3/4, 0, width/4, height); cnt++;
        line(0, height/2, width, height/2); cnt++;
        // line(width/2, 0, width/2, height); cnt++;
      }
      if (false)
      for (let i = 1; i < 4; i++) {
        const x = 200 * i;
        if (true || cnt < 1000000) {
          line(x, 0, x, height); cnt++;
        }
      }
      pop();
    }
  // }

	drawMsg("rects in the wind (epi) #genuary2508")
}

function drawMsg(msg) {
	push();

	fill("black")
	noStroke();
	textAlign(LEFT, TOP)
	text(msg, 1, 1)

	fill("white")
	noStroke();
	textAlign(LEFT, TOP)
	text(msg, 0, 0)

	pop();
}
